import{_ as o,o as t,c as a,a8 as s}from"./chunks/framework.R_sesYpn.js";const h=JSON.parse('{"title":"Versions; output format","description":"","frontmatter":{"title":"Versions; output format"},"headers":[],"relativePath":"server/rest-api/api-info.md","filePath":"server/030_rest-api/004_api-info.md","lastUpdated":1786522245000}'),r={name:"server/rest-api/api-info.md"};function i(c,e,d,n,l,u){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="general-notes-about-the-api" tabindex="-1">General notes about the API <a class="header-anchor" href="#general-notes-about-the-api" aria-label="Permalink to &quot;General notes about the API&quot;">​</a></h1> <h2 id="api-versions" tabindex="-1">API versions <a class="header-anchor" href="#api-versions" aria-label="Permalink to &quot;API versions&quot;">​</a></h2> <p>Use <code>api=4</code> or <code>api=5</code> to specify the API version to use. Configure <code>parameters.api</code> in your <code>blacklab-server.yaml</code> to set the default version to use. Without either of these, the BlackLab version will determine the API version used. Support for older version(s) is a transitionary measure and will eventually be dropped.</p> <p>Full details can be found in <a href="./miscellaneous/api-versions.html">API versions</a>.</p> <h2 id="output-format" tabindex="-1">Output format <a class="header-anchor" href="#output-format" aria-label="Permalink to &quot;Output format&quot;">​</a></h2> <p>To request a specific output format, either:</p> <ul><li>pass the HTTP header <code>Accept</code> with the value <code>application/json</code>, <code>application/xml</code> or <code>text/csv</code>, or</li> <li>pass the query parameter <code>outputformat</code> with the value <code>json</code>, <code>xml</code> or <code>csv</code>.</li></ul> <p>If both are specified, the parameter has precedence.</p> <details class="details custom-block"><summary>Notes about CSV</summary> <p>For CSV hits/docs results, the parameters <code>csvsummary</code> determines whether to include a summary of the search parameters in the output <code>[no]</code> and <code>csvsepline</code> determines whether to include a separator declaration that will help Microsoft Excel read the file <code>[no]</code>.</p> <p><code>listvalues</code> can be a comma-separated list of annotations to include in the results. <code>listmetadatavalues</code> is the same for metadata fields. <code>listspanattributes</code> for span attributes (e.g. if your document has <code>&lt;speech speaker=&quot;Joe&quot;&gt;</code> tags, then <code>listspanattributes=speech.speaker</code> will include a column with the speaker of the matched text). For each of these parameters, <code>*</code> means include all.</p> <p>If a metadata field has multiple values (e.g. if a document has multiple authors), they will be concatenated with <code>|</code> as the separator. <code>|</code>, <code>\\n</code>, <code>\\r</code> and <code>\\\\</code> will be backslash-escaped.</p> <p>As is common in CSV, values may be double-quoted if necessary (e.g. if a value contains a comma). Any double quotes already in the values will be doubled, so <code>say &quot;yes&quot;, or &quot;no&quot;?</code> will become <code>&quot;say &quot;&quot;yes&quot;&quot;, or &quot;&quot;no&quot;&quot;?&quot;</code></p></details> <p><strong>NOTE:</strong> if you&#39;re using JSON, you can see a tree view of the JSON response in most browsers using the network tab in the debug console (F12).</p>',19)])])}const m=o(r,[["render",i]]);export{h as __pageData,m as default};
